// Each stage owns its output channel.
func gen(ns ...int) <-chan int {
  out := make(chan int)
  go func() {
    for _, n := range ns {
      out <- n
    }
    close(out)
  }()
  return out
}

func add1(in <-chan int) <-chan int {
  out := make(chan int)
  go func() {
    for n := range in {
      out <- n + 1
    }
    close(out)
  }()
  return out
}

func main() {
  s := 0
  c := add1(add1(gen(1, 2)))
  for v := range c {
    s += v
  }
  fmt.Println(s)
}
